import com.smartmanager.nativeapp.*;import java.util.*;
public class MutationGuardTest { public static void main(String[] a)throws Exception{Map<String,String> x=new HashMap<>();x.put(".id","*7");x.put("disabled","false");List<Map<String,String>> rows=Collections.singletonList(x);if(MutationGuard.requireId(rows,"*7")!=x)throw new AssertionError("id");for(String bad:new String[]{"", "*8"})try{MutationGuard.requireId(rows,bad);throw new AssertionError("invalid id accepted");}catch(java.io.IOException ok){}System.out.println("PASS: CRUD mutation id validation, missing-resource and permission-safe guard");} }
